CREATE TABLE `community_device` (
  `device_id` bigint NOT NULL COMMENT '设备ID',
  `community_id` bigint DEFAULT NULL COMMENT '小区ID',
  `building_id` bigint DEFAULT NULL COMMENT '楼栋ID',
  `unit_id` bigint DEFAULT NULL COMMENT '单元ID',
  `device_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '设备名称',
  `device_code` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '设备编号',
  `device_type` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '设备类型（门禁 电梯 摄像头 消防 照明 其他）',
  `device_location` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '设备位置',
  `device_status` char(1) COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '设备状态（0正常 1故障 2维修中 3停用）',
  `online_status` char(1) COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '在线状态（0在线 1离线）',
  `manufacturer` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生产厂商',
  `install_date` date DEFAULT NULL COMMENT '安装日期',
