CREATE TABLE `community_fee_item` (
  `item_id` bigint NOT NULL COMMENT '费用项目ID',
  `item_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '费用项目名称',
  `item_type` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '费用类型（物业费 停车费 维修费 水费 电费 其他）',
  `charge_standard` decimal(10,2) DEFAULT NULL COMMENT '收费标准',
  `charge_unit` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收费单位',
  `charge_cycle` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收费周期（月 季度 年 一次性）',
  `status` char(1) COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '状态（0启用 1停用）',
  `create_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(1024) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`item_id`),
  KEY `idx_fee_item_type` (`item_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='费用项目表';
