--
-- Table structure for table `community_payment_record`
--

DROP TABLE IF EXISTS `community_payment_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `community_payment_record` (
  `payment_id` bigint NOT NULL COMMENT '缴费记录ID',
  `payment_no` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '缴费流水号',
  `bill_id` bigint DEFAULT NULL COMMENT '账单ID',
  `owner_id` bigint DEFAULT NULL COMMENT '业主ID',
  `owner_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业主姓名',
  `room_id` bigint DEFAULT NULL COMMENT '房屋ID',
  `payment_amount` decimal(10,2) DEFAULT NULL COMMENT '缴费金额',
  `payment_method` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '缴费方式（现金 微信 支付宝 银行卡）',
  `payment_status` char(1) COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '缴费状态（0待支付 1已支付 2支付失败 3已退款）',
  `payment_time` datetime DEFAULT NULL COMMENT '缴费时间',
  `operator_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '操作人员',
  `receipt_no` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '收据编号',
  `create_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(1024) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`payment_id`),
  KEY `idx_payment_bill_id` (`bill_id`),
  KEY `idx_payment_owner_id` (`owner_id`),
  KEY `idx_payment_room_id` (`room_id`),
  KEY `idx_payment_no` (`payment_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='缴费记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

