--
-- Table structure for table `community_repair_order`
--

DROP TABLE IF EXISTS `community_repair_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `community_repair_order` (
  `repair_id` bigint NOT NULL COMMENT '报修ID',
  `repair_no` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '报修单号',
  `owner_id` bigint DEFAULT NULL COMMENT '业主ID',
  `owner_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业主姓名',
  `room_id` bigint DEFAULT NULL COMMENT '房屋ID',
  `community_id` bigint DEFAULT NULL COMMENT '小区ID',
  `repair_title` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '报修标题',
  `repair_type` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '报修类型（水电 门禁 电梯 公共设施 其他）',
  `repair_location` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '报修位置',
  `repair_content` varchar(1024) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '报修内容',
  `contact_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系电话',
  `repair_images` varchar(1024) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '报修图片',
  `audit_status` char(1) COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '审核状态（0待审核 1通过 2驳回）',
  `audit_opinion` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审核意见',
  `audit_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '审核人',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `worker_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '维修人员',
  `repair_start_time` datetime DEFAULT NULL COMMENT '维修开始时间',
  `repair_finish_time` datetime DEFAULT NULL COMMENT '维修完成时间',
  `repair_result` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '维修结果',
  `repair_cost` decimal(10,2) DEFAULT NULL COMMENT '维修费用',
  `satisfaction` int DEFAULT NULL COMMENT '满意度评分（1-5）',
  `status` char(1) COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '工单状态（0待审核 1待维修 2维修中 3已完成 4已驳回）',
  `create_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(1024) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`repair_id`),
  KEY `idx_repair_order_owner_id` (`owner_id`),
  KEY `idx_repair_order_room_id` (`room_id`),
  KEY `idx_repair_order_community_id` (`community_id`),
  KEY `idx_repair_order_no` (`repair_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='报修表';
/*!40101 SET character_set_client = @saved_cs_client */;

