--
-- Table structure for table `community_vehicle`
--

DROP TABLE IF EXISTS `community_vehicle`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `community_vehicle` (
  `vehicle_id` bigint NOT NULL COMMENT '车辆ID',
  `owner_id` bigint DEFAULT NULL COMMENT '业主ID',
  `owner_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业主姓名',
  `room_id` bigint DEFAULT NULL COMMENT '房屋ID',
  `plate_no` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '车牌号',
  `vehicle_type` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '车辆类型（小型车 新能源车 SUV 其他）',
  `vehicle_brand` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '车辆品牌',
  `vehicle_color` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '车辆颜色',
  `phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '联系电话',
  `bind_status` char(1) COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '绑定状态（0已绑定 1未绑定）',
  `status` char(1) COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '车辆状态（0正常 1停用）',
  `create_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(1024) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`vehicle_id`),
  KEY `idx_vehicle_owner_id` (`owner_id`),
  KEY `idx_vehicle_room_id` (`room_id`),
  KEY `idx_vehicle_plate_no` (`plate_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='车辆信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

