--
-- Table structure for table `files`
--

DROP TABLE IF EXISTS `files`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `files` (
  `files_id` bigint NOT NULL COMMENT '文件ID',
  `files_url` varchar(500) NOT NULL COMMENT '文件地址',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人者',
  `del_flag` int DEFAULT '0' COMMENT '删除状态0默认1删除',
  `source` int DEFAULT NULL COMMENT '来源0APP端，1PC端',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `parent_id` bigint DEFAULT NULL COMMENT '父级ID',
  `user_id` bigint DEFAULT NULL COMMENT '创建人ID',
  PRIMARY KEY (`files_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='文件管理';
/*!40101 SET character_set_client = @saved_cs_client */;

