DROP TABLE IF EXISTS `sys_area`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_area` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '唯一主键',
  `code` int DEFAULT NULL COMMENT '城市编码',
  `name` varchar(40) DEFAULT NULL COMMENT '城市名称',
  `parentId` int DEFAULT NULL COMMENT '城市父ID',
  `level` int DEFAULT NULL COMMENT '城市等级(0:省,1:市,2:县)',
  `type` int DEFAULT NULL COMMENT '功能类型(1:角色认证地点开通;0:未开通)',
  `servicestate` int DEFAULT NULL COMMENT '服务状态',
  `delete_flag` int DEFAULT '0' COMMENT '逻辑删除 0正常 1 删除',
  `region` int DEFAULT NULL COMMENT '地区范围',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10270 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='区域表';
/*!40101 SET character_set_client = @saved_cs_client */;

